var ENT=[["Scrubber", "Signature Scrubber pillar of the Data Cleaning Engine framework."], ["Deduper", "Signature Deduper pillar of the Data Cleaning Engine framework."], ["Imputer", "Signature Imputer pillar of the Data Cleaning Engine framework."], ["Outlier Scout", "Signature Outlier Scout pillar of the Data Cleaning Engine framework."], ["Normalizer", "Signature Normalizer pillar of the Data Cleaning Engine framework."], ["Coercer", "Signature Coercer pillar of the Data Cleaning Engine framework."], ["Canonicalizer", "Signature Canonicalizer pillar of the Data Cleaning Engine framework."]];
